def _version_rank(model_id: str) -> float:
    """Attribue un score d'ordre selon la génération du modèle."""
    match = re.search(r"gemini-(\d+(?:\.\d+)?)", model_id.lower())
    if match:
        return float(match.group(1))
    return 1.0

